+	cpID := checkpointid.MustCheckpointID(checkpointID)
+	err = store.WriteCommitted(context.Background(), checkpoint.WriteCommittedOptions{
+		CheckpointID:     cpID,
+		SessionID:        checkpointID + "-" + strings.ReplaceAll(string(kind), "_", "-"),
