+		Branch:           "feat/review",
+		Transcript:       redact.AlreadyRedacted([]byte(`{"event":"test"}` + "\n")),
+		Prompts:          []string{"test prompt"},
+		FilesTouched:     filesTouched,
+		CheckpointsCount: 1,
+		Agent:            agentType,
+		Kind:             string(kind),
+		HasReview:        kind.IsReview(),
+	})
+	if err != nil {
+		t.Fatalf("write checkpoint: %v", err)
+	}
