   747	// before the agent launches. Zero-valued fields mean "not detected" — format
   748	// helpers degrade gracefully.
   749	type reviewScope struct {
   750		Branch       string // current branch short name; "" if detached
   751		HeadSHA      string // short HEAD SHA (always set when non-empty scope)
   752		Base         string // base branch (e.g. "main"); "" if unknown
   753		BaseRef      string // exact git ref for range commands (e.g. "origin/main"); "" if unknown
   754		AheadCommits int    // commits in baseRef..HEAD; 0 if BaseRef == ""
   755		FilesChanged int    // files in baseRef..HEAD diff; 0 if BaseRef == ""
   756		Uncommitted  int    // files from `git status --porcelain`
