   763	
   764	// detectReviewScope runs a handful of cheap `git` queries to describe the
   765	// set of changes the user is about to review. Best-effort: any individual
   766	// query that fails leaves the corresponding field at its zero value.
   767	func detectReviewScope(ctx context.Context) (reviewScope, error) {
   768		repoRoot, err := paths.WorktreeRoot(ctx)
   769		if err != nil {
   770			return reviewScope{}, fmt.Errorf("locate repo root: %w", err)
   771		}
   772		var s reviewScope
   773		s.Branch = gitString(ctx, repoRoot, "rev-parse", "--abbrev-ref", "HEAD")
   774		if s.Branch == detachedHEADDisplay {
   775			s.Branch = ""
   776		}
   777		s.HeadSHA = gitString(ctx, repoRoot, "rev-parse", "--short", "HEAD")
   778		base := detectBaseBranchRef(ctx, repoRoot)
   779		s.Base = base.display
   780		s.BaseRef = base.ref
   781		if s.BaseRef != "" && s.Branch != "" && s.Base != s.Branch {
   782			if n, ok := gitCount(ctx, repoRoot, "rev-list", "--count", s.BaseRef+".."+s.Branch); ok {
   783				s.AheadCommits = n
   784			}
   785			if files := gitString(ctx, repoRoot, "diff", "--name-only", s.BaseRef+"..."+s.Branch); files != "" {
   786				s.FilesChanged = len(strings.Split(files, "\n"))
   787			}
   788		}
   789		if status := gitString(ctx, repoRoot, "status", "--porcelain"); status != "" {
   790			s.Uncommitted = len(strings.Split(status, "\n"))
   791		}
   792		return s, nil
   793	}
