   795	// detectBaseBranch resolves a base branch name by trying, in order:
   796	// origin/HEAD → origin/main → origin/master → local main → local master.
   797	// Returns "" if none match. Remote-tracking branches come first because they
   798	// reflect the team's convention; local branches are the fallback for repos
   799	// that haven't been `git fetch`'d recently.
   800	func detectBaseBranch(ctx context.Context, repoRoot string) string {
   801		return detectBaseBranchRef(ctx, repoRoot).display
