   825	// gitString runs `git -C repoRoot <args...>` and returns trimmed stdout, or
   826	// "" on any error.
   827	func gitString(ctx context.Context, repoRoot string, args ...string) string {
   828		full := append([]string{"-C", repoRoot}, args...)
   829		out, err := exec.CommandContext(ctx, "git", full...).Output()
   830		if err != nil {
   831			return ""
   832		}
   833		return strings.TrimSpace(string(out))
   834	}
   835	
   836	// gitOK runs `git -C repoRoot <args...>` and reports whether it succeeded.
   837	func gitOK(ctx context.Context, repoRoot string, args ...string) bool {
   838		full := append([]string{"-C", repoRoot}, args...)
   839		return exec.CommandContext(ctx, "git", full...).Run() == nil
   840	}

